/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field keyingInQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableKeyingInQty extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, keyingInQty);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Enum);
    RetailInventTable retailInventTable;
    while select keyingInQty from retailInventTable
        group by keyingInQty
    {
        ret.add(retailInventTable.keyingInQty);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, keyingInQty));
    qbr.value(queryValue(_value));
}
